#include <stdio.h>
int main(void) {
    int values[] = {1, 2, 3, 4, 5};
    int total = 0;
    int count = 5;
    for (int i = 0; i < count; i++) {
        total += values[i];
    }
    printf("%d\n", total);
    return 0;
},0

#include <stdio.h>
#include <string.h>
int main(void) {
    char name[] = "compiler";
    int total = 0;
    for (int i = 0; i < 100; i++) {
        int length = (int)strlen(name);
        if (i < length) {
            total += i;
        }
    }
    printf("%d\n", total);
    return 0;
},1
